"""Shared exact soil for the RH foundations attack.

Pure numpy, no external deps. Two scales of soil:
- LINE = 0..84  : the store's own line (the S-bands' integer soil).
- x_max        : extended census bounds for asymptotic checks.
"""
from __future__ import annotations

import numpy as np

LINE_END = 84  # the store's line end (bands S8-S32 all hold line 0..84)


def spf_sieve(n_max: int) -> np.ndarray:
    """smallest-prime-factor table, spf[0]=spf[1]=1."""
    spf = np.arange(n_max + 1, dtype=np.int64)
    if n_max >= 0:
        spf[0] = 1
    if n_max >= 1:
        spf[1] = 1
    for p in range(2, int(n_max ** 0.5) + 1):
        if spf[p] == p:
            for m in range(p * p, n_max + 1, p):
                if spf[m] == m:
                    spf[m] = p
    return spf


def is_prime_arr(n_max: int) -> np.ndarray:
    """boolean prime indicator on 0..n_max (sieve of Eratosthenes)."""
    sieve = np.ones(n_max + 1, dtype=bool)
    sieve[0:2] = False
    for p in range(2, int(n_max ** 0.5) + 1):
        if sieve[p]:
            sieve[p * p :: p] = False
    return sieve


def von_mangoldt(spf: np.ndarray) -> np.ndarray:
    """Lambda(n) = log p iff n = p^k, else 0. Exact via the spf chain."""
    n_max = len(spf) - 1
    lam = np.zeros(n_max + 1)
    n = np.arange(n_max + 1)
    p = spf[n > 1]
    m = np.where(n > 1, n // p, 1)
    is_pure = m == 1
    lam[n > 1] = np.where(is_pure, np.log(p), 0.0)
    # multi-powers: Lambda(p^k) = log p for k>=1
    for k in range(2, 30):
        if (p ** k) > n_max:
            break
        pk = p ** k
        lam[pk] = np.log(p)
    return lam


def primes_upto(n_max: int) -> np.ndarray:
    return np.flatnonzero(is_prime_arr(n_max))


def line_primes() -> np.ndarray:
    """the primes on the store's line 0..84 (23 of them)"""
    return primes_upto(LINE_END)


def fib_bands_upto(line_end: int) -> list[tuple[int, int]]:
    """Fibonacci bands [F_k, F_{k+1}) covering the line."""
    a, b = 1, 1
    bands = []
    while b <= line_end:
        bands.append((a, b))
        a, b = b, a + b
    if a != b:
        bands.append((a, b))
    return bands[: -1]  # pairs (F_k, F_{k+1})

