export interface FibPair {
  readonly current: bigint;
  readonly next: bigint;
}

export const fibPairAt = (index: number): FibPair =>
  index < 2
    ? { current: BigInt(index), next: 1n }
    : (() => {
        const half: FibPair = fibPairAt(Math.floor(index / 2));
        const doubledEven: bigint = half.current * (2n * half.next - half.current);
        const doubledOdd: bigint = half.current ** 2n + half.next ** 2n;
        return index % 2 === 0
          ? { current: doubledEven, next: doubledOdd }
          : { current: doubledOdd, next: doubledEven + doubledOdd };
      })();

export const fibValueAt = (index: number): bigint => fibPairAt(index).current;

// Products reach (prime)^2 with primes up to ~2^137 (F_200 scale), so the
// running state stays in bigint; the final residue is always < prime < 2^53.
const fibPairAtModuloStep = (
  index: number,
  prime: bigint,
  bitPosition: number,
  current: bigint,
  next: bigint,
): [bigint, bigint] => {
  const doubledEven: bigint = (current * ((2n * next - current) % prime + prime)) % prime;
  const doubledOdd: bigint = (current * current + next * next) % prime;
  const bit: bigint = BigInt((index >>> bitPosition) & 1);
  const advanced: [bigint, bigint] = bit === 1n
    ? [doubledOdd, (doubledEven + doubledOdd) % prime]
    : [doubledEven, doubledOdd];
  return bitPosition < 0 ? advanced : fibPairAtModuloStep(index, prime, bitPosition - 1, advanced[0], advanced[1]);
};

export const fibModulo = (index: number, prime: bigint): bigint =>
  index < 1 ? 0n : (() => {
    const highestBit: number = Math.floor(Math.log2(index));
    const pair: [bigint, bigint] = fibPairAtModuloStep(index, prime, highestBit, 0n, 1n);
    return pair[0];
  })();

export const modPow = (base: bigint, exponent: bigint, modulus: bigint): bigint => {
  let carry: bigint = 1n;
  let remaining: bigint = exponent;
  let baseResidue: bigint = base % modulus;
  const squareBase: () => void = () => { baseResidue = (baseResidue * baseResidue) % modulus; };
  while (remaining > 0n) {
    while (remaining > 0n && (remaining & 1n) === 0n) {
      remaining >>= 1n;
      squareBase();
    }
    while (remaining > 0n && (remaining & 1n) === 1n) {
      carry = (carry * baseResidue) % modulus;
      remaining >>= 1n;
      squareBase();
    }
  }
  return carry;
};

const smallWitnessPrimes: readonly bigint[] = [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n];

// Deterministic witness sets only cover < 3.317e24; prime factors of F_n for
// n up to 200 reach ~2^137, so 28 fixed witnesses are used (false-prime
// probability < 4^-28). Cross-validated against the python baseline.
const millerRabinWitnesses: readonly bigint[] = [
  2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n,
  41n, 43n, 47n, 53n, 59n, 61n, 67n, 71n, 73n, 79n, 83n, 89n, 97n, 101n, 103n, 107n,
];

const oddPartDecompositionOf = (even: bigint): readonly [bigint, number] => {
  let oddPart: bigint = even;
  let shift: number = 0;
  while (oddPart >= 2n && (oddPart & 1n) === 0n) {
    oddPart >>= 1n;
    shift += 1;
  }
  return [oddPart, shift] as const;
};

const passesMillerRabinWitness = (witness: bigint, oddPart: bigint, shift: number, candidate: bigint): boolean => {
  let residue: bigint = modPowLocal(witness, oddPart, candidate);
  if (residue === 1n || residue === candidate - 1n) return true;
  let round: number = 0;
  while (round < shift - 1) {
    residue = (residue * residue) % candidate;
    if (residue === candidate - 1n) return true;
    if (residue === 1n) return false;
    round += 1;
  }
  return false;
};

const modPowLocal = (base: bigint, exponent: bigint, modulus: bigint): bigint => {
  let carry: bigint = 1n;
  let remaining: bigint = exponent;
  let baseResidue: bigint = base % modulus;
  while (remaining > 0n) {
    if ((remaining & 1n) === 1n) carry = (carry * baseResidue) % modulus;
    remaining >>= 1n;
    baseResidue = (baseResidue * baseResidue) % modulus;
  }
  return carry;
};

export const isProbablyPrime = (candidate: bigint): boolean => {
  const smallMatch: bigint | null = smallWitnessPrimes.find((small) => candidate === small) ?? null;
  const smallDivisor: bigint | null = smallWitnessPrimes.find((small) => small > 2n && candidate % small === 0n) ?? null;
  return (
    (smallMatch !== null ? true
      : smallDivisor !== null ? false
      : candidate < 4n ? false
      : (candidate & 1n) === 0n ? false
      : (() => {
          const [oddPart, shift] = oddPartDecompositionOf(candidate - 1n);
          return millerRabinWitnesses.every((witness) => passesMillerRabinWitness(witness, oddPart, shift, candidate));
        })())
  );
};

export const gcdOf = (valueA: bigint, valueB: bigint): bigint => {
  let left: bigint = valueA <= 0n ? -valueA : valueA;
  let right: bigint = valueB <= 0n ? -valueB : valueB;
  while (right !== 0n) {
    const remainder: bigint = left % right;
    left = right;
    right = remainder;
  }
  return left;
};

import { gcdOf } from "./gcd-of.js";

const floydIteration = (
  candidate: bigint,
  seedConstant: bigint,
  maxSteps: number,
): bigint => {
  let xPoint: bigint = 2n;
  let yPoint: bigint = 2n;
  let divergence: bigint = 1n;
  let stepsTaken: number = 0;
  while (divergence === 1n && stepsTaken < maxSteps) {
    xPoint = (xPoint * xPoint + seedConstant) % candidate;
    yPoint = (yPoint * yPoint + seedConstant) % candidate;
    yPoint = (yPoint * yPoint + seedConstant) % candidate;
    let difference: bigint = (xPoint - yPoint) % candidate;
    if (difference < 0n) difference += candidate;
    divergence = gcdOf(difference, candidate);
    stepsTaken += 1;
  }
  return divergence;
};

export const pollardRhoFactorOf = (candidate: bigint): number => {
  let seed: bigint = 1n;
  let factor: bigint;
  do {
    seed += 1n;
    factor = floydIteration(candidate, seed, 300_000);
  } while ((factor === 1n || factor >= candidate) && seed < 64n);
  return (factor > 1n && factor < candidate ? Number(factor) : Number.POSITIVE_INFINITY);
};

export const trialPrimesUpTo = (limit: number): readonly number[] => {
  const isComposite: boolean[] = new Array<boolean>(limit + 1).fill(false);
  forIndexlessSieve(isComposite, limit);
  return collectSurvivors(isComposite, limit);
};

const markMultiplesOf = (isComposite: boolean[], prime: number, limit: number): void => {
  let multiple: number = prime * prime;
  while (multiple <= limit) {
    isComposite[multiple] = true;
    multiple += prime;
  }
};

const forIndexlessSieve = (isComposite: boolean[], limit: number): void => {
  let candidate: number = 2;
  while (candidate * candidate <= limit) {
    if (!isComposite[candidate]) markMultiplesOf(isComposite, candidate, limit);
    candidate += 1;
  }
};

const collectSurvivors = (isComposite: boolean[], limit: number): number[] => {
  let collected: number[] = [];
  let candidate: number = 2;
  while (candidate <= limit) {
    collected = isComposite[candidate] ? collected : [...collected, candidate];
    candidate += 1;
  }
  return collected;
};

export interface StrippedRemainder {
  readonly remainder: bigint;
  readonly strippedPrimes: readonly number[];
}

export const stripSmallFactorRemainderOf = (
  value: bigint,
  primeList: readonly number[],
): StrippedRemainder => {
  let index: number = 0;
  let remainder: bigint = value;
  let strippedPrimes: number[] = [];
  while (index < primeList.length && remainder > 1n) {
    const prime: number | undefined = primeList[index];
    const divides: boolean = remainder !== 1n && prime !== undefined && remainder % BigInt(prime) === 0n;
    if (prime !== undefined && divides) {
      while (remainder % BigInt(prime) === 0n) remainder = remainder / BigInt(prime);
      strippedPrimes = [...strippedPrimes, prime];
    }
    index += 1;
  }
  return { remainder, strippedPrimes };
};

import { isProbablyPrime } from "./is-probably-prime.js";
import { pollardRhoFactorOf } from "./pollard-rho-factor-of.js";
import { stripSmallFactorRemainderOf } from "./strip-small-factor-remainder-of.js";
import { trialPrimesUpTo } from "./trial-primes.js";

export const distinctPrimeDivisorsOf = (
  value: bigint,
  primeList: readonly number[] = trialPrimesUpTo(10_000),
): readonly number[] => {
  const sortedUnique = (numbers: readonly number[]): readonly number[] =>
    Array.from(new Set(numbers)).sort((left, right) => left - right);

  const expand: (leftover: bigint) => number[] = (leftover: bigint): number[] => {
    if (leftover === 1n) return [];
    const factor: number = isProbablyPrime(leftover)
      ? Number(leftover)
      : pollardRhoFactorOf(leftover);
    const factorAsBig: bigint = factor === Number.POSITIVE_INFINITY ? leftover : BigInt(factor);
    const coFactorAsBig: bigint = leftover / factorAsBig;
    const merged: number[] = [
      ...expand(factorAsBig === 1n || factor === Number.POSITIVE_INFINITY ? 1n : factorAsBig),
      ...expand(coFactorAsBig),
    ];
    return merged;
  };

  const { remainder, strippedPrimes } = stripSmallFactorRemainderOf(value, primeList);
  return sortedUnique([...strippedPrimes, ...expand(remainder)]);
};

import { trialPrimesUpTo } from "./trial-primes.js";

export const primeFactorsOfIndex = (
