import { primeFactorsOfIndex } from "./prime-factors-of-index.js";

const shrinkToExactOrder = (
  candidate: number,
  prime: bigint,
  factors: readonly number[],
): number => {
  let runningCandidate: number = candidate;
  let factorIndex: number = 0;
