import { trialPrimesUpTo } from "./trial-primes.js";

export const primeFactorsOfIndex = (
  index: number,
  primeList: readonly number[] = trialPrimesUpTo(10_000),
): readonly number[] => {
  let collected: number[] = [];
  let remaining: number = index;
