  while (scanIndex < primeList.length && remaining > 1) {
    const prime: number = primeList[scanIndex]!;
    if (remaining % prime === 0) {
      collected = [...collected, prime];
      while (remaining % prime === 0) remaining = Math.floor(remaining / prime);
    }
    scanIndex += 1;
  }
  return collected;
};

import { trialPrimesUpTo } from "./trial-primes.js";

export const eulerPhiOf = (
  value: number,
  primeList: readonly number[] = trialPrimesUpTo(10_000),
): number => {
  let remaining: number = value;
  let runningPhi: number = value;
  let scanIndex: number = 0;
  while (
    scanIndex < primeList.length &&
    remaining > 1 &&
    primeList[scanIndex]! * primeList[scanIndex]! <= remaining
  ) {
    const prime: number = primeList[scanIndex]!;
    if (remaining % prime === 0) {
      while (remaining % prime === 0) remaining = Math.floor(remaining / prime);
      runningPhi = Math.floor(runningPhi / prime) * (prime - 1);
    }
    scanIndex += 1;
  }
  const leftoverTail: number = remaining > 1 ? Math.floor(runningPhi / remaining) * (remaining - 1) : 0;
  return runningPhi - leftoverTail;
};

export interface ComplexValue {
  readonly re: number;
  readonly im: number;
}

export const addComplex = (left: ComplexValue, right: ComplexValue): ComplexValue => ({
  re: left.re + right.re,
  im: left.im + right.im,
});

export const absOfComplex = (value: ComplexValue): number =>
  Math.hypot(value.re, value.im);

import type { ComplexValue } from "./complex-value.js";

export const complexPowerTermForLog = (
  realPartOfExponent: number,
  imaginaryPartOfExponent: number,
  logOfBase: number,
): ComplexValue => {
  const magnitude: number = Math.exp(-realPartOfExponent * logOfBase);
  const phase: number = -imaginaryPartOfExponent * logOfBase;
  return {
    re: magnitude * Math.cos(phase),
    im: magnitude * Math.sin(phase),
  };
};

// chi_5(n) = (5/n): residues of n mod 5 are 0 -> 0, 1 -> +1, 2 -> -1, 3 -> -1, 4 -> +1.
const chi5ResiduesByModuloFive: readonly number[] = [0, 1, -1, -1, 1];

export const chi5At = (n: number): number => chi5ResiduesByModuloFive[((n % 5) + 5) % 5]!;

// A(N) = sum_{n <= N} chi_5(n): full 5-periods sum to 0, so only the
// residue tail of the final partial period remains.
export const chi5CumulativeResidueAt = (n: number): number => {
  const partialPeriodLength: number = n % 5;
  let accumulated: number = 0;
  let position: number = 1;
  while (position <= partialPeriodLength) {
    accumulated += chi5At(position);
    position += 1;
  }
  return accumulated;
};

import type { ComplexValue } from "./complex-value.js";

// L(s, chi_5) via exact 5-periodic blocking: sum over full blocks
// m = 0..blockCount-1 of chi-weighted (5m+r)^{-s} for r = 1..4.
// Converges like blockCount^{-(sigma + 1)}; the block form and the raw
// sequential sum are independent summation orders, so their agreement is a
// coding cross-check, not merely a self-consistency.
export const l5BlockReferenceAt = (
  realPartOfExponent: number,
  imaginaryPartOfExponent: number,
  blockCount: number,
): ComplexValue => {
  const residues: readonly number[] = [1, 2, 3, 4];
  const weights: readonly number[] = [1, -1, -1, 1];
  let accumulated: ComplexValue = { re: 0, im: 0 };
  let block: number = 0;
  while (block < blockCount) {
    let residueIndex: number = 0;
    while (residueIndex < residues.length) {
      const argument: number = 5.0 * block + residues[residueIndex]!;
      const logOfArgument: number = Math.log(argument);
      const magnitude: number = Math.exp(-realPartOfExponent * logOfArgument);
      const phase: number = -imaginaryPartOfExponent * logOfArgument;
      const sign: number = weights[residueIndex]!;
      accumulated = {
        re: accumulated.re + sign * magnitude * Math.cos(phase),
        im: accumulated.im + sign * magnitude * Math.sin(phase),
      };
      residueIndex += 1;
    }
    block += 1;
  }
  return accumulated;
};

// Sequential partial sums P_N(s) = sum_{n <= N} chi_5(n) n^{-s} for
// N = 1..count, returned as parallel re/im arrays (index n-1 holds P_n).
export const chi5SequentialPartialSums = (
  realPartOfExponent: number,
  imaginaryPartOfExponent: number,
  count: number,
): readonly [Float64Array, Float64Array] => {
  const realRunning: Float64Array = new Float64Array(count);
  const imaginaryRunning: Float64Array = new Float64Array(count);
  let runningRe: number = 0;
  let runningIm: number = 0;
  let n: number = 1;
  while (n <= count) {
    const residue: number = n % 5;
    const magnitude: number = Math.exp(-realPartOfExponent * Math.log(n));
    const phase: number = -imaginaryPartOfExponent * Math.log(n);
    const sign: number = residue === 0 ? 0 : residue === 1 || residue === 4 ? 1 : -1;
    runningRe += sign * magnitude * Math.cos(phase);
    runningIm += sign * magnitude * Math.sin(phase);
    realRunning[n - 1] = runningRe;
    imaginaryRunning[n - 1] = runningIm;
    n += 1;
  }
  return [realRunning, imaginaryRunning] as const;
};

export interface PowerLawFit {
  readonly amplitude: number;
  readonly exponent: number;
}

// Least-squares fit of log(magnitude) ~ log(amplitude) + exponent * log(x).
export const powerLawLeastSquaresFit = (
  xValues: readonly number[],
  magnitudes: readonly number[],
): PowerLawFit => {
  const usablePairs: readonly [number, number][] = xValues
    .map((x, position) => [x, magnitudes[position]!] as [number, number])
    .filter((pair) => pair[0] > 0 && pair[1] > 0);
  const pairCount: number = usablePairs.length;
  const sumLogX: number = usablePairs.reduce((total, pair) => total + Math.log(pair[0]), 0);
  const sumLogY: number = usablePairs.reduce((total, pair) => total + Math.log(pair[1]), 0);
  const sumLogXLogY: number = usablePairs.reduce((total, pair) => total + Math.log(pair[0]) * Math.log(pair[1]), 0);
  const sumLogXLogX: number = usablePairs.reduce((total, pair) => total + Math.log(pair[0]) ** 2, 0);
  const denominator: number = pairCount * sumLogXLogX - sumLogX ** 2;
  const exponent: number = denominator === 0 ? 0 : (pairCount * sumLogXLogY - sumLogX * sumLogY) / denominator;
  const amplitude: number = Math.exp((sumLogY - exponent * sumLogX) / pairCount);
  return { amplitude, exponent };
};

export interface CrossCheckRecord {
  readonly label: string;
  readonly measured: number;
  readonly expected: number;
  readonly tolerance: number;
}

export interface CrossCheckSummary {
  readonly passed: boolean;
  readonly records: readonly CrossCheckRecord[];
}

export const evaluateCrossCheckRecord = (record: CrossCheckRecord): boolean =>
  Math.abs(record.measured - record.expected) <= record.tolerance;

export const summarizeCrossChecks = (records: readonly CrossCheckRecord[]): CrossCheckSummary => ({
  passed: records.every(evaluateCrossCheckRecord),
  records,
});

