export const distinctPrimeDivisorsOf = (
  value: bigint,
  primeList: readonly number[] = trialPrimesUpTo(10_000),
): readonly number[] => {
  const sortedUnique = (numbers: readonly number[]): readonly number[] =>
    Array.from(new Set(numbers)).sort((left, right) => left - right);

  const expand: (leftover: bigint) => number[] = (leftover: bigint): number[] => {
    const factor: number = leftover === 1n
      ? 1
      : isProbablyPrime(leftover) ? Number(leftover) : pollardRhoFactorOf(leftover);
    const factorAsBig: bigint = leftover === 1n ? 1n : factor === Number.POSITIVE_INFINITY ? leftover : BigInt(factor);
    const coFactorAsBig: bigint = leftover === 1n ? 1n : leftover / factorAsBig;
    return [
      ...expand(factorAsBig),
      ...expand(coFactorAsBig),
    ];
  };

  const { remainder, strippedPrimes } = stripSmallFactorRemainderOf(value, primeList);
  return sortedUnique([...strippedPrimes, ...expand(remainder)]);
};

