// run-law-chi5.ts — the chi_5 missing-term law (fusion bridge from the
// Fibonacci primitive-prime bands into the zeta missing-term hierarchy).
//
// Law under test (measured on zeta day 4, to be re-measured here):
//   sum_{n > N} chi_5(n) n^{-s} = -A(N) N^{-s} + (2s/5) N^{-s-1} + O(N^{-s-2})
// so  |L5(s) - P_N(s) + A(N) N^{-s}| ~ c(t) N^{-3/2},  c(t) = |2s/5| + O(1/N).
// Goldens: c(t=1) = 0.4471 (0.44721 predicted = |2(0.5+i)/5|); the raw T0
// per-decade ratio is exactly 10^{1.5} = 31.62 at A(N) = 0 points; the T1
// exponent is -1.5.

import { l5BlockReferenceAt } from "./l5-block-reference-at.js";
import { chi5SequentialPartialSums } from "./chi5-sequential-partial-sums.js";
import { chi5CumulativeResidueAt } from "./chi5-residue.js";
import { complexPowerTermForLog } from "./complex-power-term-for-log.js";
import { absOfComplex } from "./complex-value.js";
import { powerLawLeastSquaresFit } from "./power-law-least-squares-fit.js";
import { summarizeCrossChecks } from "./cross-check-summary.js";

const BLOCK_COUNT: number = 100_000;
const T_VALUES: readonly number[] = [1, 2, 5, 10, 20, 50, 100, 200, 500, 1000];
const N_VALUES: readonly number[] = [1_000, 10_000, 100_000];

const lawMeasurementAtT = (t: number) => {
  const l5Reference: { re: number; im: number } = l5BlockReferenceAt(0.5, t, BLOCK_COUNT);
  const [partialRe, partialIm] = chi5SequentialPartialSums(0.5, t, BLOCK_COUNT);
  const rawMagnitudes: number[] = [];
  const correctedMagnitudes: number[] = [];
  N_VALUES.forEach((n) => {
    const partial: { re: number; im: number } = {
      re: partialRe[n - 1]!,
      im: partialIm[n - 1]!,
    };
    rawMagnitudes.push(absOfComplex({ re: l5Reference.re - partial.re, im: l5Reference.im - partial.im }));
    const residueTerm: { re: number; im: number } = complexPowerTermForLog(0.5, t, Math.log(n));
    const residueRescaled: { re: number; im: number } = {
      re: chi5CumulativeResidueAt(n) * residueTerm.re,
      im: chi5CumulativeResidueAt(n) * residueTerm.im,
    };
    correctedMagnitudes.push(
      absOfComplex({ re: l5Reference.re - partial.re + residueRescaled.re, im: l5Reference.im - partial.im + residueRescaled.im }),
    );
  });
  const exponentFit: { amplitude: number; exponent: number } = powerLawLeastSquaresFit(N_VALUES, correctedMagnitudes);
  return { rawMagnitudes, correctedMagnitudes, exponentFit };
};

const main = () => {
  const measurements: { t: number; rawMagnitudes: number[]; correctedMagnitudes: number[]; exponentFit: { amplitude: number; exponent: number } }[] =
    T_VALUES.map((t) => ({ t, ...lawMeasurementAtT(t) }));

  const crossChecks = measurements.map((measurement) => {
    const measuredCoefficient: number = measurement.correctedMagnitudes[1]! / Math.pow(measurement.t === 1 ? 1 : measurement.t, 0) / Math.pow(10_000, -1.5);
    void measuredCoefficient;
    const tOne: number = measurement.t === 1 ? measurement.correctedMagnitudes[1]! * Math.pow(10_000, 1.5) : 0;
    void tOne;
    return null;
  });
  void crossChecks;

  const tOneMeasurement = measurements.find((measurement) => measurement.t === 1)!;
  const coefficientAtTOne: number = tOneMeasurement.correctedMagnitudes[1]! * Math.pow(10_000, 1.5);
  // c(t) = |2s/5| * N-independent part: the measured law's coefficient at t.
  const measuredCoefficientByT: readonly number[] = measurements.map((measurement) =>
    measurement.correctedMagnitudes[1]! * Math.pow(10_000, 1.5),
  );

  const decadeRatioRaw: number =
    (tOneMeasurement.rawMagnitudes[2]! / tOneMeasurement.rawMagnitudes[1]!) *
    (tOneMeasurement.rawMagnitudes[1]! / tOneMeasurement.rawMagnitudes[0]!);

  const summary = summarizeCrossChecks([
    {
      label: "c(t=1) matches 0.4471 (4-digit python baseline)",
      measured: coefficientAtTOne,
      expected: 0.4471,
      tolerance: 2e-3,
    },
    {
      label: "c(t) is t-independent to 2% (law: |2s/5|, weak N-dependence only)",
      measured: Math.max(...measuredCoefficientByT) / Math.min(...measuredCoefficientByT),
      expected: 1.0,
      tolerance: 0.02,
    },
    {
      label: "raw per-decade ratio at t=1 is 10^{1.5} = 31.62",
      measured: decadeRatioRaw,
      expected: 31.62,
      tolerance: 0.4,
    },
    {
      label: "corrected exponent is -3/2 (python: -1.492 at t=1)",
      measured: tOneMeasurement.exponentFit.exponent,
      expected: -1.5,
      tolerance: 0.05,
    },
  ]);

  console.log("chi_5 missing-term law (TypeScript re-measurement)");
  console.log("=================================================");
  measurements.forEach((measurement) => {
    console.log(
      `t=${String(measurement.t).padStart(5)}  T0=[${measurement.rawMagnitudes.map((magnitude) => magnitude.toFixed(3e-3)).join(", ")}]  T1exp=${measurement.exponentFit.exponent.toFixed(4)}  c(t)=${(measurement.correctedMagnitudes[1]! * Math.pow(10_000, 1.5)).toFixed(4)}`,
    );
  });
  console.log("\ncross-checks vs python baseline:");
  summary.records.forEach((record) => {
    console.log(`  ${record.label}: ${Math.abs(record.measured - record.expected) <= record.tolerance ? "PASS" : "FAIL"} (measured ${record.measured.toFixed(5)}, expected ${record.expected})`);
  });

  process.exitCode = summary.passed ? 0 : 1;
};

main();

// run-law-chi5.ts — the chi_5 missing-term law (fusion bridge from the
