import { l5BlockReferenceAt } from "./l5-block-reference-at.js";
import { chi5SequentialPartialSums } from "./chi5-sequential-partial-sums.js";
import { chi5CumulativeResidueAt } from "./chi5-residue.js";
import { complexPowerTermForLog } from "./complex-power-term-for-log.js";
import { absOfComplex } from "./complex-value.js";
import { powerLawLeastSquaresFit } from "./power-law-least-squares-fit.js";
import { summarizeCrossChecks, type CrossCheckRecord } from "./cross-check-summary.js";

const BLOCK_COUNT: number = 100_000;
const T_VALUES: readonly number[] = [1, 10, 100, 1000];
// N values all divisible by 5, so the A(N) residue term is exactly zero and
// the raw tail obeys the pure power law across the measured grid.
const N_VALUES: readonly number[] = [1_000, 10_000, 100_000];
const COEFFICIENT_N_REFERENCE: number = 10_000;

const measuredCoefficientAt = (correctedMagnitudes: readonly number[]): number =>
  correctedMagnitudes[1]! * Math.pow(COEFFICIENT_N_REFERENCE, 1.5);

const predictedCoefficientAtT = (t: number): number => (2 / 5) * Math.sqrt(1 + t * t);

const lawMeasurementAtT = (t: number) => {
  const l5Reference: { re: number; im: number } = l5BlockReferenceAt(0.5, t, BLOCK_COUNT);
  const [partialRe, partialIm] = chi5SequentialPartialSums(0.5, t, BLOCK_COUNT);
  const rawMagnitudes: number[] = [];
  const correctedMagnitudes: number[] = [];
  N_VALUES.forEach((n) => {
    const partialReHere: number = partialRe[n - 1]!;
    const partialImHere: number = partialIm[n - 1]!;
    rawMagnitudes.push(
      absOfComplex({ re: l5Reference.re - partialReHere, im: l5Reference.im - partialImHere }),
    );
    const residueTerm: { re: number; im: number } = complexPowerTermForLog(0.5, t, Math.log(n));
    const residueSign: number = chi5CumulativeResidueAt(n);
    correctedMagnitudes.push(
      absOfComplex({
        re: l5Reference.re - partialReHere + residueSign * residueTerm.re,
        im: l5Reference.im - partialImHere + residueSign * residueTerm.im,
      }),
    );
  });
  const exponentFit: { amplitude: number; exponent: number } =
    powerLawLeastSquaresFit(N_VALUES, correctedMagnitudes);
  return { t, rawMagnitudes, correctedMagnitudes, exponentFit };
};

const main = (): void => {
  const measurements: ReturnType<typeof lawMeasurementAtT>[] = T_VALUES.map(lawMeasurementAtT);
  const tOneMeasurement: ReturnType<typeof lawMeasurementAtT> = measurements[0]!;

  const crossCheckRecords: CrossCheckRecord[] = [
    {
      label: "c(t=1) = 0.4471 to 4 digits (python baseline)",
      measured: measuredCoefficientAt(tOneMeasurement.correctedMagnitudes),
      expected: 0.4471,
      tolerance: 2e-3,
    },
    {
      label: "c(t) tracks |2s/5| = (2/5) sqrt(1 + t^2) at every measured t (2%)",
      measured: Math.max(
        ...measurements.map((measurement) => Math.abs(measuredCoefficientAt(measurement.correctedMagnitudes) - predictedCoefficientAtT(measurement.t)) / predictedCoefficientAtT(measurement.t)),
      ),
      expected: 0,
      tolerance: 0.02,
    },
    {
      label: "raw per-decade decay 10^{3/2}: two-decade ratio T0(1e5)/T0(1e3) at t=1 = 10^3",
      measured: tOneMeasurement.rawMagnitudes[2]! / tOneMeasurement.rawMagnitudes[0]!,
      expected: 1000,
      tolerance: 20,
    },
    {
      label: "corrected exponent -3/2 (python: -1.492 at t=1)",
      measured: tOneMeasurement.exponentFit.exponent,
      expected: -1.5,
      tolerance: 0.05,
    },
  ];
  const summary = summarizeCrossChecks(crossCheckRecords);

  console.log("chi_5 missing-term law (TypeScript re-measurement)");
  console.log("=================================================");
  measurements.forEach((measurement) => {
    console.log(
      `t=${String(measurement.t).padStart(5)}  T0=[${measurement.rawMagnitudes
        .map((magnitude) => magnitude.toExponential(4))
        .join(", ")}]  T1exp=${measurement.exponentFit.exponent.toFixed(4)}  c(t)=${measuredCoefficientAt(
        measurement.correctedMagnitudes,
      ).toFixed(4)}  c_pred=${predictedCoefficientAtT(measurement.t).toFixed(4)}`,
    );
  });
  console.log("\ncross-checks vs python baselines:");
  summary.records.forEach((record) => {
    const passes: boolean = Math.abs(record.measured - record.expected) <= record.tolerance;
    console.log(`  ${passes ? "PASS" : "FAIL"}  ${record.label} (measured ${record.measured.toFixed(5)}, expected ${record.expected})`);
  });

  process.exitCode = summary.passed ? 0 : 1;
};

main();

// run-band-density.ts — Fibonacci primitive-prime band density (the
// "interesting side" of the fusion: where the bands live analytically).
//
// B(n) = sum of 1/q over the primitive prime divisors q of F_n, where q is
// primitive when the multiplicative order of phi = (1+sqrt5)/2 mod q is
// exactly n (Zsigmondy: every n outside {6, 12} has at least one).
// S(N) = sum_{n=3..N} B(n). Python goldens: S(10) = 0.70285, S(20) =
// 0.90405, S(100) = 1.26539; power-law fit S ~ N^0.24 over the measured
// range; B(9) = 1/17; B(6) = B(12) = 0 (Zsigmondy exceptions).

import { fibPairAt } from "./fib-pair-at.js";
import { distinctPrimeDivisorsOf } from "./distinct-prime-divisors-of.js";
import { isPrimitiveDivisorOfBand } from "./is-primitive-divisor-of-band.js";
import { powerLawLeastSquaresFit } from "./power-law-least-squares-fit.js";
import { summarizeCrossChecks, type CrossCheckRecord } from "./cross-check-summary.js";

const BAND_UPPER: number = 100;

// B(n) in double: the reciprocal 1/q uses Number(q) — q reaches ~10^21 at
// n = 100, and the double's 15-16 significant digits keep each reciprocal
// accurate to ~1e-16 relative, far below the 1e-4 reporting precision.
const bandReciprocalSumAt = (bandIndex: number): number => {
  const fibonacciValue: bigint = fibPairAt(bandIndex).current;
  const divisors: readonly bigint[] = distinctPrimeDivisorsOf(fibonacciValue);
  const primitiveDivisors: bigint[] = divisors.filter((divisor) => isPrimitiveDivisorOfBand(divisor, bandIndex));
  return primitiveDivisors.reduce((total: number, divisor: bigint): number => total + 1 / Number(divisor), 0);
};

const main = (): void => {
  const bandSummaries: { bandIndex: number; bandSum: number; runningSum: number }[] = [];
  let runningTotal: number = 0;
  for (let bandIndex = 3; bandIndex <= BAND_UPPER; bandIndex += 1) {
    const bandSum: number = bandReciprocalSumAt(bandIndex);
    runningTotal += bandSum;
    bandSummaries.push({ bandIndex, bandSum, runningSum: runningTotal });
  }

  const runningAt = (n: number): number => bandSummaries.find((entry) => entry.bandIndex === n)!.runningSum;
  const sValues: number[] = [10, 20, 50, 100].map(runningAt);
  const nValues: number[] = [10, 20, 50, 100];
  const fit: { amplitude: number; exponent: number } = powerLawLeastSquaresFit(nValues, sValues);

  const crossCheckRecords: CrossCheckRecord[] = [
    { label: "S(10) = 0.70285 (python baseline)", measured: runningAt(10), expected: 0.70285, tolerance: 5e-5 },
    { label: "S(20) = 0.90405 (python baseline)", measured: runningAt(20), expected: 0.90405, tolerance: 5e-5 },
    { label: "S(100) = 1.26539 (python baseline)", measured: runningAt(100), expected: 1.26539, tolerance: 2e-4 },
    { label: "B(9) = 1/17 = 0.058824 (17 primitive for band 9)", measured: bandSummaries.find((entry) => entry.bandIndex === 9)!.bandSum, expected: 1 / 17, tolerance: 1e-12 },
    { label: "B(6) = 0 (Zsigmondy exception)", measured: bandSummaries.find((entry) => entry.bandIndex === 6)!.bandSum, expected: 0, tolerance: 1e-15 },
    { label: "B(12) = 0 (Zsigmondy exception)", measured: bandSummaries.find((entry) => entry.bandIndex === 12)!.bandSum, expected: 0, tolerance: 1e-15 },
    { label: "power-law exponent 0.24 (python: 0.2429 over the same range)", measured: fit.exponent, expected: 0.2429, tolerance: 0.015 },
  ];
  const summary = summarizeCrossChecks(crossCheckRecords);

  console.log("Fibonacci primitive-prime band density (TypeScript re-measurement)");
  console.log("=================================================================");
  const reportMarks: readonly number[] = [5, 10, 20, 50, 100];
  bandSummaries
    .filter((entry) => reportMarks.includes(entry.bandIndex))
    .forEach((entry) => {
      console.log(`n=${String(entry.bandIndex).padStart(3)}  B(n)=${entry.bandSum.toExponential(6)}  S(n)=${entry.runningSum.toFixed(5)}`);
    });
  console.log(`power-law fit: S(N) ~ ${fit.amplitude.toFixed(3)} * N^${fit.exponent.toFixed(4)}`);
  console.log("\ncross-checks vs python baselines:");
  summary.records.forEach((record) => {
    const passes: boolean = Math.abs(record.measured - record.expected) <= record.tolerance;
    console.log(`  ${passes ? "PASS" : "FAIL"}  ${record.label} (measured ${record.measured.toFixed(6)}, expected ${record.expected.toFixed(6)})`);
  });

  process.exitCode = summary.passed ? 0 : 1;
};

main();

