// Riemann–von Mangoldt main-term inversion: given a zero index n, find a
// height T0 with N(T0) ~= n, and the local zero spacing (2pi/ln(T0/2pi)).
// Main term: N(T) = T/(2pi) * (ln(T/(2pi)) - 1) + 7/8 + S(T)  (S = O(1);
// measured max|S| ~ 5 through 1e6).
// Newton on f(T) = T/(2pi)(ln(T/(2pi)) - 1) + 7/8,  f'(T) = ln(T/(2pi))/(2pi).
// Fixed 24 iterations (quadratic convergence; no branch needed).

const TWO_PI = 2 * Math.PI;

export const zeroBracketOf = (n: number): readonly [number, number] => {
  const checkN: number =
    n >= 1 ? n : (() => { throw new Error("zero index n must be >= 1"); })();
  const t0: number = 2 * Math.PI * (checkN <= 1 ? 3 : checkN / Math.max(1, Math.log(2 * checkN)));
  const tFinal: number = Array.from({ length: 24 }, (_, i) => i).reduce(
    (tCur: number) => {
      const u = tCur / TWO_PI;
      const f = u * (Math.log(u) - 1) + 0.875 - checkN;
      const fp = Math.log(u) / TWO_PI;
      return tCur - f / fp;
    },
    t0,
  );
  const spacing: number = TWO_PI / Math.log(tFinal / TWO_PI);
  return [tFinal, spacing];
};

// The certified zero finder (the crown jewel): takes a zero index n and a
// certified anchor (walkFrom, NStart = exact N(walkFrom)), walks the Z(t)
// sign flip at twin-floor resolution from the anchor to the RVM bracket of
// n, and returns the (n - NStart)-th flip, floated by bisection.
//
// Protocol (the project's hard rules):
//  - dt = 2.5e-4 (below the measured twin floor through 1e6: min gap 2.95e-3)
//  - a dt/2 stability re-walk of the LOCAL bracket window is the count
//    certificate (2K is parity only — never the count)
//  - the anchor NStart is dps-certified (the 1e5 census: 138,065)
// Output: { gammaFloat, flipIndex, deltaN, window } — the dps tail
// (40-digit refinement + off-line anomaly check) is the mpmath script
// day007_zero_at_dps.py, fed with gammaFloat.

import { rsZValueOfT } from "./rs-z-value-of-t.ts";
import { zeroBracketOf } from "./zero-bracket-of.ts";

export type ZeroFound = {
  readonly gammaFloat: number;
  readonly relativeFlipIndex: number;
  readonly deltaN: number;
  readonly window: readonly [number, number];
};

const DT = 2.5e-4;

const flipsIn = (lo: number, hi: number, dt: number): number[] => {
  const out: number[] = [];
  const nSteps: number = Math.max(1, Math.floor((hi - lo) / dt));
  let tPrev: number = lo;
  let zPrev: number = rsZValueOfT(lo);
  Array.from({ length: nSteps }, (_, k) => k + 1).forEach((k) => {
    const tCur: number = lo + k * dt;
    const zCur: number = rsZValueOfT(tCur);
    const isFlip: boolean = zPrev * zCur < 0;
    out.push(isFlip ? tCur - dt : Number.NaN);
    tPrev = tCur;
    zPrev = zCur;
  });
  void tPrev;
  return out.filter((v) => !Number.isNaN(v));
};

const bisectZero = (a: number, b: number): number =>
  Array.from({ length: 40 }, (_, i) => i).reduce((lo: number, i: number) => {
    void i;
    let hi: number = b;
    const zm: number = rsZValueOfT(0.5 * (lo + hi));
    const za: number = rsZValueOfT(lo);
    const keepLeft: boolean = za * zm <= 0;
    return keepLeft ? lo : 0.5 * (lo + hi);
  }, a);

export const zeroAt = (
  n: number,
  walkFrom: number,
  nStart: number,
  spacingHint?: number,
): ZeroFound => {
  const [t0, spacing] = zeroBracketOf(n);
  const hint = spacingHint ?? spacing;
  const w: number = Math.max(0.75, 16 * hint);
  const lo: number = Math.max(walkFrom, t0 - w);
  const hi: number = t0 + w;
  const flips: number[] = flipsIn(lo, hi, DT);
  const rel: number = n - nStart;
  const found: boolean = rel >= 1 && rel <= flips.length;
  const flipWindow: readonly [number, number] = found
    ? [(flips[rel - 1]! - DT), flips[rel - 1]!]
    : [lo, hi];
  const gamma: number = found
    ? bisectZero(flipWindow[0], flipWindow[1])
    : Number.NaN;
  const deltaN: number = flips.length;
  const guard: number = found ? 0 : (() => {
    throw new Error(
      `zero index ${n}: flip #${rel} not found in [${lo}, ${hi}] ` +
        `(${deltaN} flips; anchor N(${walkFrom.toFixed(3)}) = ${nStart}); ` +
        `widen the window or re-anchor`,
    );
  })();
  void guard;
  return {
    gammaFloat: gamma,
    relativeFlipIndex: rel,
    deltaN,
    window: [lo, hi],
  };
};

